customCSS:
.t, .history { color: #8790a0; }
.join { color: #608e32; }
.part, .quit { color: #8790a0; }
.kick, .error { color: #d05858; }
.notice { color: #be7e05; }
.action { color: #b05ccc; }
.mode, .nick, .topic, .server { color: #3a8b84; }
.highlight { color: #4b505b; background-color: #e8ebf0; border-left: 3px solid #b05ccc; padding-left: 8px; }
.reply { color: #8790a0; border-left: 2px solid #5079be; padding-left: 6px; }
.oper { color: #fafafa; background-color: #be7e05; }
.reactions { color: #5079be; background-color: #e8ebf0; }
.card { background-color: #e8ebf0; border-color: #8790a0; }
.card-title { color: #5079be; }
.card-desc { color: #8790a0; }
.daychange { color: #8790a0; border-color: #e8ebf0; }
